mapper.select:
SELECT S.ORDER_ID as orderId, '${effective}' as orderStatus, CONCAT(CONCAT(CONCAT(PP.PORTFOLIO_NAME ,'('), PP.PORTFOLIO_ID),')') as portfolioId, PP.PARENT_PORTFOLIO_ID ACT_PORTFOLIO_ID, PP.PORTFOLIO_NAME as portfolioName, case S.PS when '${IE_FLAG_02}' then S.MY_ACCT_NO else S.COUNTER_ACCT_NO end as myAcctNo, case S.PS when '${IE_FLAG_02}' then S.COUNTER_ACCT_NO else S.MY_ACCT_NO end as counterAcctNo, T.PS as payType, S.SETTLE_AMT as settleAmt, S.SETTLE_DATE as settleDate, T.TRADE_ID as tradeId, null as workflowId FROM STL_DVP_ORDERS S LEFT JOIN STL_DVP_TRADE_MATCH SDTM ON S.ORDER_ID = SDTM.ORDER_ID LEFT JOIN TRD_PRODUCT_DEAL T ON T.TRADE_ID = SDTM.TRADE_ID LEFT JOIN PTL_TRADE PT ON T.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y' AND T.IS_CANCEL = #{yesNo_no} AND T.TRADE_STATUS = #{TRADE_STATUS_01}
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND ( pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item}
)
AND ((S.COUNTER_ACCT_NO = #{counterAcctNo} AND S.PS = '02') OR (S.MY_ACCT_NO = #{counterAcctNo} AND S.PS = '01'))
AND ((S.COUNTER_ACCT_NO = #{myAcctNo} AND S.PS = '01') OR (S.MY_ACCT_NO = #{myAcctNo} AND S.PS = '02'))
AND T.PS = #{payType}
AND S.SETTLE_DATE BETWEEN STR_TO_DATE(#{dataDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{dataDateEnd},'%Y-%m-%d')
AND T.PS IN
#{item}
UNION ALL
SELECT S.ORDER_ID as orderId, '${revoked}' as orderStatus, CONCAT(CONCAT(CONCAT(PP.PORTFOLIO_NAME,'('),PP.PORTFOLIO_ID),')') as portfolioId, null ACT_PORTFOLIO_ID, PP.PORTFOLIO_NAME as portfolioName, case S.PS when '${IE_FLAG_02}' then S.MY_ACCT_NO else S.COUNTER_ACCT_NO end as myAcctNo, case S.PS when '${IE_FLAG_02}' then S.COUNTER_ACCT_NO else S.MY_ACCT_NO end as counterAcctNo, T.PS as payType, S.SETTLE_AMT as settleAmt, S.SETTLE_DATE as settleDate, T.TRADE_ID as tradeId, null as workflowId FROM STL_DVP_ORDERS S LEFT JOIN STL_DVP_TRADE_MATCH SDTM ON S.ORDER_ID = SDTM.ORDER_ID LEFT JOIN TRD_PRODUCT_DEAL T ON T.TRADE_ID = SDTM.TRADE_ID LEFT JOIN PTL_TRADE PT ON T.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
PP.INVEST_YESORNO = 'Y' AND T.IS_CANCEL = #{yesNo_no} AND T.TRADE_STATUS = #{TRADE_STATUS_03}
AND ( pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item}
)
AND S.COUNTER_ACCT_NO = #{counterAcctNo}
AND S.MY_ACCT_NO = #{myAcctNo}
AND T.PS = #{payType}
AND S.SETTLE_DATE BETWEEN STR_TO_DATE(#{dataDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{dataDateEnd},'%Y-%m-%d')
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND T.PS IN
#{item}
order by settleDate desc, portfolioId
